-- SB-56: marks a household's first-run setup as finished. NULL means the
-- creator is still in the setup flow.
-- Generated by drizzle-kit; hand edits: this header and the backfill, which
-- has to run before the unique index so existing households (created before
-- the flow existed) count as finished and are never sent to /setup.

ALTER TABLE "households" ADD COLUMN "setup_completed_at" timestamp with time zone;--> statement-breakpoint
UPDATE "households" SET "setup_completed_at" = now();--> statement-breakpoint
CREATE UNIQUE INDEX "households_created_by_unfinished_setup_key" ON "households" USING btree ("created_by") WHERE "households"."setup_completed_at" is null;
